def main():
    os.makedirs(OUT, exist_ok=True)
    assert set(P.keys()) == set(IDS), (set(IDS) - set(P.keys()), set(P.keys()) - set(IDS))
    for cid in IDS:
        rec = {"case_id": cid, "prediction_text": P[cid]["prediction_text"], "basis": P[cid]["basis"],
               "confidence": P[cid]["confidence"], "trigger": P[cid]["trigger"]}
        with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
    # validation: exact id list only, no glob
    n = 0; tc = {"changed_main":0,"reserve_used":0,"disputed":0}
    for cid in IDS:
        with open(os.path.join(OUT, cid + ".json"), encoding="utf-8") as f:
            r = json.load(f)
        assert set(r.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}, (cid, r.keys())
        assert r["case_id"] == cid
        assert isinstance(r["prediction_text"], str) and r["prediction_text"]
        assert isinstance(r["basis"], str) and r["basis"]
        assert isinstance(r["confidence"], (int,float)) and 0 <= r["confidence"] <= 1
        assert set(r["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}
        for k in ("changed_main","reserve_used","disputed"):
            assert isinstance(r["trigger"][k], bool)
            tc[k] += int(r["trigger"][k])
        assert isinstance(r["trigger"]["reason"], str)
        n += 1
    print(f"WROTE {n} files; trigger counts: {tc}")

if __name__ == "__main__":
    main()
